 "content": "def transform(grid):
    """Move numbered markers along their fixed rays; crossings spawn 4-rays."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    rays = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 1:
                # Two cells east, then one cell north.
                path = [(r, c + 1), (r, c + 2), (r - 1, c + 2)]
            elif color == 2:
                path = [(r, c - i) for i in range(1, 5)]
            elif color == 3:
                path = [(r + i, c) for i in range(1, 4)]
            elif color == 6:
                path = [(r - i, c) for i in range(1, 7)]
            else:
                continue
            # The movement reaches the boundary and stops there if its
            # prescribed endpoint would otherwise fall outside the grid.
            valid = []
            for y, x in path:
                if not (0 <= y < h and 0 <= x < w):
                    break
                valid.append((y, x))
            rays.append((color, valid))

    # Mark paths, recording all intersections between distinct moving markers.
    owners = {}
    crossings = set()
    for idx, (color, path) in enumerate(rays):
        for j, (y, x) in enumerate(path):
            previous = owners.get((y, x))
            if previous is not None and previous != idx:
                crossings.add((y, x))
            owners[(y, x)] = idx
            if j == len(path) - 1:
                out[y][x] = color
            else:
                out[y][x] = 5

    # Every crossing emits a southwest diagonal of color 4, to the edge.
    for r, c in crossings:
        y, x = r + 1, c - 1
        while 0 <= y < h and 0 <= x < w:
            # The collision ray is visible over the background/trails; retain
            # any pre-existing numbered marker at its destination.
            if grid[y][x] == 0 or out[y][x] == 5:
                out[y][x] = 4
            y += 1
            x -= 1
        out[r][c] = 4
    return out
